with latest as (select *, row_number() over (partition by product_id order by quantity, id) as rank_in_group from inventory qualify rank_in_group = 1) select case when quantity >= 187 then 'PREMIUM' else 'STANDARD' end as quantity_tier, approx_percentile(quantity, 0.9) as quantity_p90, approx_percentile(quantity, array(0.25, 0.5, 0.75)) as quantity_quartiles, max(quantity) as max_quantity from latest group by case when quantity >= 187 then 'PREMIUM' else 'STANDARD' end
